'use strict';
const CACHE='bep-family-v6-simple-screens';
const ASSETS=['./','./index.html','./styles.css','./seed.js','./core.js','./app.js','./spending-core.js','./family-features.js','./purchase-units.js','./unit-picker.js','./recipe-catalog.js','./planning-core.js','./shopping-planning.js','./push-ui.js','./simple-view.js','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('bep-family-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(url.pathname.startsWith('/.netlify/'))return;if(event.request.method==='POST'&&url.pathname==='/share-notes'){event.respondWith((async()=>{const form=await event.request.formData();let text=String(form.get('text')||'');const file=form.get('notes');if(file&&file.size<=1000000)text+='\n'+await file.text();const cache=await caches.open('bep-note-inbox');await cache.put('/shared-notes-draft',Response.json({title:String(form.get('title')||''),text:text.slice(0,100000)}));return Response.redirect(new URL('/#import-notes',url.origin),303)})());return}if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&ASSETS.some(path=>new URL(path,self.location.href).href===event.request.url)){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy))}return response}).catch(()=>caches.match(event.request).then(cached=>cached||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});
self.addEventListener('push',event=>{let data={};try{data=event.data?.json()||{}}catch(e){}event.waitUntil(self.registration.showNotification(data.title||'Bếp Gia Đình',{body:data.body||'Nhà mình có việc bếp cần xem.',icon:'./icon-192.png',tag:data.tag||'bep-reminder',data:{url:['/#today','/#shopping','/#planner','/#expenses','/#pantry'].includes(data.url)?data.url:'/#today'}}))});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(list=>{const target=new URL(event.notification.data?.url||'./#today',self.location.href).href;const client=list.find(c=>new URL(c.url).origin===self.location.origin);if(client){client.navigate(target);return client.focus()}return clients.openWindow(target)}))});
